import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.BC3NdntU.js";const u=JSON.parse('{"title":"11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致)","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md","lastUpdated":1788776592000}'),i={name:"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md"};function o(r,s,p,l,h,d){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_11-7-提示词工程-下-推理增强-cot-tot-react-自我一致" tabindex="-1">11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致) <a class="header-anchor" href="#_11-7-提示词工程-下-推理增强-cot-tot-react-自我一致" aria-label="Permalink to &quot;11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致)&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 难度:⭐⭐⭐ 专家 | 阅读时间:25min</p></blockquote><hr><h2 id="引言-让模型-想清楚再答" tabindex="-1">引言:让模型&quot;想清楚再答&quot; <a class="header-anchor" href="#引言-让模型-想清楚再答" aria-label="Permalink to &quot;引言:让模型&quot;想清楚再答&quot;&quot;">​</a></h2><p>上一章解决&quot;<strong>说清楚要什么</strong>&quot;,这一章解决&quot;<strong>让模型答得更对</strong>&quot;——核心是诱导模型<strong>显式推理</strong>,而不是直接蹦答案。</p><hr><h2 id="一、思维链-cot-chain-of-thought" tabindex="-1">一、思维链(CoT,Chain of Thought) <a class="header-anchor" href="#一、思维链-cot-chain-of-thought" aria-label="Permalink to &quot;一、思维链(CoT,Chain of Thought)&quot;">​</a></h2><p><strong>让模型把推理步骤写出来</strong>,复杂任务正确率显著提升:</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">问题:一个篮子里有 3 个苹果,又放进 2 个,再拿走 1 个,剩几个?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请一步步推理:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 初始 3 个</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 放入 2 个 → 5 个</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 拿走 1 个 → 4 个</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">答案:4 个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>为什么有效?</strong></p><blockquote><p>自回归模型一次只能预测&quot;下一个 token&quot;。直接要答案,等于让它在<strong>一步之内</strong>算出复杂推理;而 CoT 把推理拆成<strong>一串 token</strong>,每一步都只做一小步——难度被摊薄,中间步骤还能自我纠错。</p></blockquote><p><strong>触发方式:</strong></p><ul><li><strong>Zero-shot CoT</strong>:加一句&quot;让我们一步步思考&quot;(Let&#39;s think step by step)</li><li><strong>Few-shot CoT</strong>:示例里就展示&quot;推理 + 答案&quot;的完整过程</li></ul><hr><h2 id="二、自我一致性-self-consistency" tabindex="-1">二、自我一致性(Self-Consistency) <a class="header-anchor" href="#二、自我一致性-self-consistency" aria-label="Permalink to &quot;二、自我一致性(Self-Consistency)&quot;">​</a></h2><p><strong>同一个问题采样多次,取&quot;多数投票&quot;的结果:</strong></p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">answers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [model.ask(q, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">temperature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 采样 5 次</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">final </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> majority_vote(answers)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>原理:推理题单次可能&quot;想歪&quot;,但<strong>多次独立采样</strong>,正确路径更容易成为多数。适合有唯一正确答案的推理任务(数学、逻辑、选择题)。</p></blockquote><hr><h2 id="三、思维树-tot-tree-of-thoughts" tabindex="-1">三、思维树(ToT,Tree of Thoughts) <a class="header-anchor" href="#三、思维树-tot-tree-of-thoughts" aria-label="Permalink to &quot;三、思维树(ToT,Tree of Thoughts)&quot;">​</a></h2><p>比 CoT 更进一层:<strong>不只走一条推理链,而是同时展开多条、评估、回溯</strong>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        问题</span></span>
<span class="line"><span>       /  |  \\</span></span>
<span class="line"><span>    思路A 思路B 思路C     ← 同时探索多条</span></span>
<span class="line"><span>      |    |    |</span></span>
<span class="line"><span>    评估  评估  评估      ← 各自打分</span></span>
<span class="line"><span>      |         |</span></span>
<span class="line"><span>    剪枝      深入(选最优分支继续)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p>ToT 适合&quot;<strong>解空间大、需要搜索</strong>&quot;的任务(下棋、规划、谜题)。工程上常简化为&quot;多候选 + 打分选优&quot;。</p></blockquote><hr><h2 id="四、react-把推理接上工具-回到主线" tabindex="-1">四、ReAct:把推理接上工具(回到主线) <a class="header-anchor" href="#四、react-把推理接上工具-回到主线" aria-label="Permalink to &quot;四、ReAct:把推理接上工具(回到主线)&quot;">​</a></h2><p>11.2 的 ReAct 是&quot;推理增强 + 工具调用&quot;的合体:推理(Thought)之后<strong>接一个真实动作(Action)</strong>,而非只在脑子里想。</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Question: 2024 年诺贝尔物理学奖得主是谁?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Thought: 我不知道最新消息,需要查。→ 调用 search(&quot;2024 诺贝尔物理奖&quot;)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observation: 霍普菲尔德、辛顿</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Thought: 拿到答案,总结。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Answer: 约翰·霍普菲尔德 和 杰弗里·辛顿</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p><strong>为什么 ReAct 比纯 CoT 强?</strong> 纯 CoT 只能&quot;靠脑内知识推&quot;,知识截止或记错就错;ReAct 让模型<strong>用工具去拿事实</strong>,把&quot;推理&quot;和&quot;查证&quot;结合——这正是 Agent 优于聊天模型的根本(呼应 11.1 的&quot;事实靠工具锚定&quot;)。</p></blockquote><hr><h2 id="五、其他实用技巧-速记" tabindex="-1">五、其他实用技巧(速记) <a class="header-anchor" href="#五、其他实用技巧-速记" aria-label="Permalink to &quot;五、其他实用技巧(速记)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技巧</th><th>做法</th><th>场景</th></tr></thead><tbody><tr><td><strong>角色扮演</strong></td><td>指定专家身份</td><td>提升特定领域质量</td></tr><tr><td><strong>结构化输出</strong></td><td>锁 JSON/表格(11.6)</td><td>程序可解析</td></tr><tr><td><strong>反思(Reflexion)</strong></td><td>让模型评价自己上次的结果再改进</td><td>迭代优化</td></tr><tr><td><strong>分解(Decomposition)</strong></td><td>大任务拆子任务逐个解</td><td>复杂任务</td></tr><tr><td><strong>动态提示</strong></td><td>根据中间结果动态生成下轮提示</td><td>长流程</td></tr></tbody></table><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CoT:显式写推理步骤,摊薄单步难度(零样本/少样本触发)</span></span>
<span class="line"><span>自我一致:多次采样 + 多数投票(唯一答案题)</span></span>
<span class="line"><span>ToT:多分支探索 + 评估回溯(解空间大的搜索题)</span></span>
<span class="line"><span>ReAct:推理接工具,用事实锚定推理(Agent 核心)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="七、思考题" tabindex="-1">七、思考题 <a class="header-anchor" href="#七、思考题" aria-label="Permalink to &quot;七、思考题&quot;">​</a></h2><p><strong>Q1:CoT 为什么能提升复杂推理的正确率?</strong></p><p>因为它把&quot;一步到位算出答案&quot;拆成<strong>一串小步 token</strong>,每步只做一小步推理、难度摊薄;且中间步骤写进上下文,模型能<strong>看到并纠正</strong>前面的偏差。自回归的&quot;下一步预测&quot;天然适合这种逐步展开。</p><p><strong>Q2:什么时候该用 ReAct 而不是纯 CoT?</strong></p><p>当任务<strong>依赖外部事实或需要真实动作</strong>时(查最新信息、调用工具、执行代码、逐步验证),用 ReAct;纯 CoT 只适合&quot;<strong>不依赖外部、纯靠脑内推理</strong>&quot;的题(数学、逻辑)。一旦需要&quot;碰世界&quot;,就必须 ReAct——事实靠工具拿,而不是靠模型记。</p><hr><p>📎 参考:Chain-of-Thought 论文(Wei et al.)、Tree of Thoughts 论文、ReAct 论文、Self-Consistency 论文</p>`,42)])])}const k=a(i,[["render",o]]);export{u as __pageData,k as default};
